size_t RegisterJPEGImage(void) {
  static const char *JPEGDescription = "JPEG image format";
  static const char *JPEGMimeType = "image/jpeg";
  MagickInfo *magick_info;
  size_t entry_size;

  magick_info = (MagickInfo *) Acquire MagickMemory(sizeof(MagickInfo));
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  (void) FormatMagickString(magick_info->version, MAGICK_PATH_MAX, "%d.%d.%d", MAGICK_VERSION_MAJOR, MAGICK_VERSION_MINOR, MAGICK_VERSION_RELEASE);

  magick_info->decoder = JPEGDecoder;
  magick_info->encoder = JPEGEncoder;
  magick_info->thread_support = MagickLibrarySupportsThreading() != MagickFalse;
  magick_info->mime_type = MagickDuplicateString(JPEGMimeType);
  magick_info->description = MagickDuplicateString(JPEGDescription);
  magick_info->blob_support = MagickTrue;
  magick_info->raw_support = MagickFalse;
  magick_info->seekable_stream_support = MagickTrue;

  magick_info = CloneMagickInfo(magick_info);
  magick_info->name = "JPE";
  RegisterMagickInfo(magick_info);

  magick_info = CloneMagickInfo(magick_info);
  magick_info->name = "JPEG";
  RegisterMagickInfo(magick_info);

  magick_info = CloneMagickInfo(magick_info);
  magick_info->name = "JPG";
  RegisterMagickInfo(magick_info);

  magick_info = CloneMagickInfo(magick_info);
  magick_info->name = "JPS";
  RegisterMagickInfo(magick_info);

  magick_info = CloneMagickInfo(magick_info);
  magick_info->name = "PJPEG";
  RegisterMagickInfo(magick_info);

  entry_size = sizeof(MagickInfo);

  return entry_size;
}

