size_t RegisterJPEGImage(void) {
    MagickInfo
        *magick_info;

    MagickInfo
        *magick_info_next;

    char
        version[MaxTextLength];

    size_t
        signature;

    /* JPEG version string */
    (void) FormatMagickVersionString(version,MaxTextLength);

    /* Initialize main JPEG MagickInfo entry */
    magick_info = AcquireMagickInfo("JPEG","JPEG",
      "JPEG image format");
    magick_info->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info->flags |=CoderThreadSupport;

    /* Check JPEG library version for thread support */
    if ((JPEG_LIB_VERSION >= 70) && (JPEG_LIB_VERSION <= 99))
        magick_info->flags |= ThreadSupport;

    magick_info->mime_type = ConstantString("image/jpeg");

    /* Register main JPEG entry */
    signature = RegisterMagickInfo(magick_info);

    /* Create and register additional entries for other JPEG identifiers */
    magick_info_next = AcquireMagickInfo("JPEG","JPE",JPEG_image_format);
    magick_info_next->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info_next->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info_next->flags |=CoderThreadSupport;
    magick_info_next->flags |= magick_info->flags & ThreadSupport;
    magick_info_next->mime_type = ConstantString("image/jpeg");
    signature += RegisterMagickInfo(magick_info_next);

    magick_info_next = AcquireMagickInfo("JPEG","JPG",JPEG_image_format);
    magick_info_next->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info_next->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info_next->flags |=CoderThreadSupport;
    magick_info_next->flags |= magick_info->flags & ThreadSupport;
    magick_info_next->mime_type = ConstantString("image/jpeg");
    signature += RegisterMagickInfo(magick_info_next);

    magick_info_next = AcquireMagickInfo("JPEG","JPS",JPEG_image_format);
    magick_info_next->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info_next->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info_next->flags |=CoderThreadSupport;
    magick_info_next->flags |= magick_info->flags & ThreadSupport;
    magick_info_next->mime_type = ConstantString("image/jpeg");
    signature += RegisterMagickInfo(magick_info_next);

    magick_info_next = AcquireMagickInfo("JPEG","PJPEG",JPEG_image_format);
    magick_info_next->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info_next->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info_next->flags |=CoderThreadSupport;
    magick_info_next->flags |= magick_info->flags & ThreadSupport;
    magick_info_next->mime_type = ConstantString("image/jpeg");
    signature += RegisterMagickInfo(magick_info_next);

    return signature;
}

